css:
.loader {
  width: 20px;
  height: 52px;
  border-radius: 10px;
  box-sizing: border-box;
  background: repeating-linear-gradient(45deg, #6366f1 0 8px, #eef2ff 8px 16px);
  background-size: 100% 200%;
  box-shadow: inset 3px 0 5px rgba(0, 0, 0, 0.15), inset -3px 0 5px rgba(0, 0, 0, 0.15);
  animation: roll 0.9s linear infinite;
}
@keyframes roll {
  from { background-position: 0 0; }
  to { background-position: 0 -22.63px; }
}
